/**
 * V-102: an occurrence generated by the engine is written at local noon of its
 * due day, not at local midnight, so it keeps its day and its month across any
 * move of less than 11 hours (REGISTRE V-102, Owner decision 4, pass 78).
 * Transactions already stored are not rewritten.
 *
 * The engine wrote each occurrence at the local midnight of its due day
 * (walkOccurrences cursor = startOfDay, recurrenceDates.ts:85/95; engine
 * dto.date, RecurringTransactionEngine.ts:357), stored as a UTC instant
 * (mappers.ts:77) and read back with local getters. Any move west then showed
 * it on the day before, and an occurrence due on the 1st was counted in the
 * month - or the year - that had just ended.
 *
 * Rules are created through RecurringTransactionRepository.create and caught
 * up by the engine the way the app runs it at launch, over a real SQLite
 * database with the write guard armed. A month is the local month key the
 * dashboard, the budgets and the reports build (useDashboard.ts:107,
 * useBudgets.ts:120, useReports.ts:188); a year is the one
 * calculateYearToDateSummary reads (ytdSummary.ts:62).
 *
 * Zones (register policy no. 9): fixtures use the LOCAL Date constructor and
 * the clock is pinned with pinClock, so the suite holds in whatever zone the
 * process runs in; it is run under TZ=UTC, Africa/Lagos and America/New_York.
 * A device moving to another zone is simulated in the stored data, as in
 * recurringEndScheduleEditZone.test.ts: every stored instant is moved by the
 * zone difference. Lagos (UTC+1) to Toronto (UTC-5 from 1 Nov) is 6 h west.
 * Not proved by this: a real zone switch in ICU or Hermes, a DST change at the
 * moment of the move, or anything on a device.
 */

import { createTestDb } from '../../../tests/helpers/createTestDb';
import { pinClock, restoreZoneClock } from '../../../tests/helpers/zoneClock';
import { calculateYearToDateSummary } from '../../domain/calculations/ytdSummary';
import { CategoryType } from '../../domain/entities/Category';
import { RecurrenceFrequency, type RecurringTransaction } from '../../domain/entities/RecurringTransaction';
import { type Transaction, TransactionType } from '../../domain/entities/Transaction';
import { WalletType } from '../../domain/entities/Wallet';
import { CategoryRepository } from '../repositories/CategoryRepository';
import { RecurringTransactionRepository } from '../repositories/RecurringTransactionRepository';
import { TransactionRepository } from '../repositories/TransactionRepository';
import { WalletRepository } from '../repositories/WalletRepository';
import { processRecurringRules } from '../services/RecurringTransactionEngine';
import type { SqlDatabase } from '../storage/sql/SqlDatabase';

const BANK = 'w-bank';
const CATEGORY = 'cat-bills';
const NOTE = 'Rent';
const HOUR_MS = 60 * 60 * 1000;

let db: SqlDatabase;
let recurringRepo: RecurringTransactionRepository;
let walletRepo: WalletRepository;
let categoryRepo: CategoryRepository;
let transactionRepo: TransactionRepository;

/** Pin the clock to a local wall-clock instant in the process zone. `month` is 1-based. */
function pinAt(year: number, month: number, day: number, hours: number, minutes = 0): void {
    pinClock(new Date(year, month - 1, day, hours, minutes).getTime());
}

const pad = (n: number) => String(n).padStart(2, '0');
/** The local calendar day of `d` in the process zone. */
const ymd = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
/** The local month key, built as useDashboard.ts:107 builds it. */
const monthKey = (d: Date) => `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, '0')}`;

/** Every row the rule wrote, oldest first. */
async function ruleRows(): Promise<Transaction[]> {
    return (await transactionRepo.getAll())
        .filter((t) => t.note === NOTE)
        .sort((a, b) => a.date.getTime() - b.date.getTime());
}

/** The row of occurrence `index`; exactly one must exist. */
async function rowOf(index: number): Promise<Transaction> {
    const rows = (await ruleRows()).filter((t) => t.recurringOccurrenceIndex === index);
    expect(rows).toHaveLength(1);
    return rows[0];
}

/** How many rows each local month holds. */
async function rowsByMonth(): Promise<Record<string, number>> {
    const counts: Record<string, number> = {};
    for (const t of await ruleRows()) {
        const key = monthKey(t.date);
        counts[key] = (counts[key] ?? 0) + 1;
    }
    return counts;
}

async function runEngine(): Promise<number> {
    const result = await processRecurringRules({
        recurringRepo,
        transactionRepo,
        walletRepo,
        categoryRepo,
        eventBus: { emit: jest.fn(), emitMultiple: jest.fn() },
        runInTransaction: db.runInTransaction.bind(db),
    });
    expect(result.errors).toEqual([]);
    return result.transactionsGenerated;
}

/** A monthly expense of 1000 created the way the app creates it, starting at the pinned clock. */
async function createRuleNow(): Promise<string> {
    const rule = await db.runInTransaction(() => recurringRepo.create({
        type: TransactionType.EXPENSE,
        amount: 1000,
        walletId: BANK,
        categoryId: CATEGORY,
        description: NOTE,
        startDate: new Date(),
        frequency: RecurrenceFrequency.MONTHLY,
        interval: 1,
    }));
    return rule.id;
}

/**
 * The device moves to a zone `hoursEast` hours east of the zone that wrote the
 * data (negative: west): every stored instant is moved by that amount. Same
 * simulation as recurringEndScheduleEditZone.test.ts - moveDeviceEast.
 */
async function moveDeviceEast(hoursEast: number): Promise<void> {
    const shift = (iso: unknown) => new Date(new Date(String(iso)).getTime() + hoursEast * HOUR_MS).toISOString();
    const { rows: rules } = await db.execute('SELECT id, start_date, end_date, last_generated_date FROM recurring_rules');
    for (const r of rules) {
        await db.runInTransaction(() => db.execute(
            'UPDATE recurring_rules SET start_date = ?, end_date = ?, last_generated_date = ? WHERE id = ?',
            [shift(r.start_date), r.end_date === null ? null : shift(r.end_date), shift(r.last_generated_date), r.id],
        ));
    }
    const { rows: txs } = await db.execute('SELECT id, date FROM transactions');
    for (const t of txs) {
        await db.runInTransaction(() => db.execute('UPDATE transactions SET date = ? WHERE id = ?', [shift(t.date), t.id]));
    }
}

async function storedRule(id: string): Promise<RecurringTransaction> {
    const rule = await recurringRepo.getById(id);
    expect(rule).not.toBeNull();
    return rule!;
}

beforeEach(async () => {
    db = await createTestDb({ writeGuard: true });
    recurringRepo = new RecurringTransactionRepository(db);
    walletRepo = new WalletRepository(db);
    categoryRepo = new CategoryRepository(db);
    transactionRepo = new TransactionRepository(db);

    await db.runInTransaction(() => walletRepo.save({ id: BANK, name: 'Bank', balance: 10000000, type: WalletType.BANK, createdAt: new Date(2025, 0, 1) }));
    await db.runInTransaction(() => categoryRepo.save({ id: CATEGORY, name: 'Bills', type: CategoryType.EXPENSE }));
});

afterEach(() => {
    restoreZoneClock();
});

describe('V-102 a generated occurrence keeps its day and month after a move west (process zone; run under TZ=UTC, Africa/Lagos, America/New_York)', () => {
    it('V-102 B1. monthly on the 1st, the 1 Nov occurrence generated in Lagos and read in Toronto (6 h west): it shows 1 Nov and counts in November', async () => {
        pinAt(2026, 10, 1, 9, 0);
        const id = await createRuleNow();
        await runEngine();
        pinAt(2026, 11, 1, 9, 0);
        await runEngine();

        await moveDeviceEast(-6);

        const november = await rowOf(1);
        const rule = await storedRule(id);
        expect({
            day: ymd(november.date),
            month: monthKey(november.date),
            lastGenerated: ymd(rule.lastGeneratedDate),
            byMonth: await rowsByMonth(),
        }).toEqual({
            day: '2026-11-01',
            month: '2026-11',
            lastGenerated: '2026-11-01',
            byMonth: { '2026-10': 1, '2026-11': 1 },
        });
    });

    it('V-102 B2. monthly on the 1st, the 1 Jan occurrence generated in Lagos and read in Toronto (6 h west): it shows 1 Jan and counts in the new year', async () => {
        pinAt(2026, 12, 1, 9, 0);
        await createRuleNow();
        await runEngine();
        pinAt(2027, 1, 1, 9, 0);
        await runEngine();

        await moveDeviceEast(-6);

        const january = await rowOf(1);
        const rows = await ruleRows();
        expect({
            day: ymd(january.date),
            in2026: calculateYearToDateSummary(rows, 2026).transactionCount,
            in2027: calculateYearToDateSummary(rows, 2027).transactionCount,
        }).toEqual({
            day: '2027-01-01',
            in2026: 1,
            in2027: 1,
        });
    });

    it('control: V-98 public claim - after a one-hour move west, each monthly occurrence is generated once', async () => {
        pinAt(2026, 10, 1, 10, 0);
        await createRuleNow();
        const first = await runEngine();

        await moveDeviceEast(-1);

        // A launch the same local day after the move, then one a month later.
        pinAt(2026, 10, 1, 10, 0);
        const sameDay = await runEngine();
        pinAt(2026, 11, 1, 10, 0);
        const nextMonth = await runEngine();

        const rows = await ruleRows();
        expect({
            generated: [first, sameDay, nextMonth],
            keys: rows.map((t) => [t.recurringScheduleVersion, t.recurringOccurrenceIndex]),
        }).toEqual({
            generated: [1, 0, 1],
            keys: [[0, 0], [0, 1]],
        });
    });

    it('control: an occurrence already stored at local midnight, as 1.1.3 wrote it, is left unchanged by a later run', async () => {
        pinAt(2026, 10, 1, 10, 0);
        const id = await createRuleNow();
        // Occurrence 0 as the 1.1.3 engine wrote it: at local midnight of its
        // due day, with its occurrence key, and the rule's number moved past it.
        const midnightIso = new Date(2026, 9, 1).toISOString();
        await db.runInTransaction(async () => {
            await db.execute(
                `INSERT INTO transactions
                    (id, type, amount, category_id, wallet_id, date, note, created_at,
                     recurring_rule_id, recurring_schedule_version, recurring_occurrence_index)
                 VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
                ['old-0', TransactionType.EXPENSE, 1000, CATEGORY, BANK, midnightIso, NOTE, midnightIso, id, 0, 0],
            );
            await db.execute(
                'UPDATE recurring_rules SET last_generated_index = 0, last_generated_date = ? WHERE id = ?',
                [midnightIso, id],
            );
        });

        pinAt(2026, 11, 1, 10, 0);
        const generated = await runEngine();

        const { rows } = await db.execute("SELECT date FROM transactions WHERE id = 'old-0'");
        expect({
            generated,
            storedDate: rows[0].date,
            keys: (await ruleRows()).map((t) => t.recurringOccurrenceIndex),
        }).toEqual({
            generated: 1,
            storedDate: midnightIso,
            keys: [0, 1],
        });
    });
});
